PRAGMA foreign_keys = ON;
CREATE TABLE sources(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,url TEXT NOT NULL UNIQUE,type TEXT NOT NULL DEFAULT 'RSS',priority TEXT NOT NULL DEFAULT 'MEDIUM',language TEXT NOT NULL DEFAULT 'EN',enabled INTEGER NOT NULL DEFAULT 1,content_enrichment_enabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE articles(id INTEGER PRIMARY KEY AUTOINCREMENT,source_id INTEGER NOT NULL REFERENCES sources(id),url TEXT NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT,content TEXT,published_at TEXT,collected_at TEXT NOT NULL,translation TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX articles_time ON articles(published_at,collected_at);
CREATE TABLE watchlists(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE keywords(id INTEGER PRIMARY KEY AUTOINCREMENT,watchlist_id INTEGER NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE,keyword TEXT NOT NULL COLLATE NOCASE,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(watchlist_id,keyword));
CREATE TABLE article_keyword_matches(article_id INTEGER NOT NULL REFERENCES articles(id) ON DELETE CASCADE,keyword_id INTEGER NOT NULL REFERENCES keywords(id) ON DELETE CASCADE,PRIMARY KEY(article_id,keyword_id));
CREATE TABLE daily_briefs(id INTEGER PRIMARY KEY AUTOINCREMENT,watchlist_id INTEGER NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE,brief_date TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(watchlist_id,brief_date));
CREATE TABLE analyses(id INTEGER PRIMARY KEY AUTOINCREMENT,brief_id INTEGER NOT NULL UNIQUE REFERENCES daily_briefs(id) ON DELETE CASCADE,result TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,username TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE login_attempts(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE job_locks(name TEXT PRIMARY KEY,owner TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE job_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,status TEXT NOT NULL,summary TEXT,created_at TEXT NOT NULL);
